  let end = zonedInstant(day.year, day.month, day.day, digestHour, timeZone);
  if (end > reference.getTime()) {
    day = shiftYmd(day, -1);
    end = zonedInstant(day.year, day.month, day.day, digestHour, timeZone);
  }
  const prev = shiftYmd(day, -1);
  const start = zonedInstant(prev.year, prev.month, prev.day, digestHour, timeZone);

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
}
